<script setup>
import { computed,ref } from 'vue';
import { d10,fdate,ftime,lc } from '../../lib/client-info';
const props=defineProps({bundle:Object,metrics:Object});
const filter=ref('');
function type(value){const text=lc(value);if(text.includes('appointment'))return['blue','📅'];if(text.includes('diet'))return['green','🥗'];if(/pending|due|balance|payment/.test(text))return['orange','₹'];if(text.includes('feedback'))return['amber','⭐'];if(text.includes('unjoined'))return['red','👤'];if(text.includes('existing'))return['teal','📞'];if(/treatment|therapy/.test(text))return['purple','🩺'];if(text.includes('maintenance'))return['slate','🔄'];if(/complaint|concern/.test(text))return['red','🗣️'];return['slate','📌'];}
const types=computed(()=>{const counts=new Map();for(const row of props.bundle.followups){const name=row.followup_type||'Other';counts.set(name,(counts.get(name)||0)+1);}return [...counts].sort((a,b)=>b[1]-a[1]);});
const completed=row=>['completed','closed','done'].includes(lc(row.status));
const late=row=>d10(row.next_followup_date)&&d10(row.next_followup_date)<props.metrics.t&&!completed(row)&&lc(row.status)!=='cancelled';
const filtered=computed(()=>props.bundle.followups.filter(row=>!filter.value||(row.followup_type||'Other')===filter.value));
const stats=computed(()=>[['📞','Total',props.bundle.followups.length,''],['🟡','Open',props.metrics.openFu.length,props.metrics.openFu.length?'warn':''],['⏰','Overdue',props.metrics.overdueFu.length,props.metrics.overdueFu.length?'neg':'ok'],['✅','Completed',props.bundle.followups.filter(completed).length,'ok'],['📵','Not reachable',props.bundle.followups.filter(row=>lc(row.status).includes('not reachable')||lc(row.call_outcome).includes('not reachable')).length,'warn']]);
</script>
<template><div v-if="!bundle.followups.length" class="c3-center c3-empty"><div class="c3-state-ic">📞</div><h3>No followups</h3><p>Followups logged for this client will show here with full call history.</p></div><div v-else><div class="c3-kpis"><div v-for="[icon,label,value,color] in stats" :key="label" class="c3-kpi"><span class="c3-kpi-ic">{{ icon }}</span><div><small>{{ label }}</small><b :class="color?'tone-'+color:''">{{ value }}</b></div></div></div><div class="c3-filters" data-fu-f><button type="button" class="c3-fbtn" :class="{'is-on':!filter}" data-f="" @click="filter=''">All ({{ bundle.followups.length }})</button><button v-for="[name,count] in types" :key="name" type="button" class="c3-fbtn" :class="['f-'+type(name)[0],{'is-on':filter===name}]" :data-f="name" @click="filter=name">{{ type(name)[1] }} {{ name }} ({{ count }})</button></div><div class="c3-cards c3-c2" data-fu-list><article v-for="row in filtered" :key="row.name" class="c3-card c3-fu" :class="['f-'+type(row.followup_type)[0],{'is-late':late(row)}]" :data-type="row.followup_type||'Other'"><header class="c3-card-h"><div><span class="c3-pill c3-fu-type">{{ type(row.followup_type)[1] }} {{ row.followup_type||'Followup' }}</span><small>📅 {{ fdate(row.followup_date||row.creation) }} {{ row.followup_time?ftime(row.followup_time):'' }}</small></div><span class="c3-pill" :class="'tone-'+(completed(row)?'ok':lc(row.status).includes('not reachable')?'neg':'warn')">{{ row.status||'Open' }}</span></header><p class="c3-fu-remark">{{ row.remarks||row.client_response||'No remarks recorded.' }}</p><p v-if="row.client_response&&row.remarks" class="c3-fu-resp">💬 Client said: {{ row.client_response }}</p><div class="c3-grid c3-g3"><div v-for="[label,value] in [['By',row.employee_name||row.employee||row.followup_by||'—'],['Channel',row.contact_channel||'—'],['Outcome',row.call_outcome||'—'],['Priority',row.priority||'Normal'],['Branch',row.branch||'—']]" :key="label" class="c3-kv" :class="{'is-neg':label==='Priority'&&lc(row.priority)==='high'}"><small>{{ label }}</small><b>{{ value }}</b></div><div class="c3-kv"><small>Next followup</small><b :class="{'tone-neg':late(row)}">{{ row.next_followup_date?fdate(row.next_followup_date)+(late(row)?' ⏰ due':''):'—' }}</b></div></div><div v-if="row.linked_invoice||row.linked_appointment||row.linked_therapy_plan" class="c3-mini">🔗 {{ [row.linked_invoice,row.linked_appointment,row.linked_therapy_plan].filter(Boolean).join(', ') }}</div></article></div></div></template>
